package com.gymflex.controller;
import com.gymflex.entity.*; import com.gymflex.service.GymService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class MemberRestController {private final GymService s; public MemberRestController(GymService s){this.s=s;} @GetMapping("/members") public List<Member> all(){return s.members();} @PostMapping("/members") public ResponseEntity<?> add(@Valid @RequestBody Member m,@RequestParam Long planId){try{return ResponseEntity.ok(s.register(m,planId));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}} @PutMapping("/members/{id}/renew") public ResponseEntity<?> renew(@PathVariable Long id,@RequestParam Long planId){try{return ResponseEntity.ok(s.renew(id,planId));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}} @PostMapping("/members/{id}/checkin") public ResponseEntity<?> check(@PathVariable Long id){try{return ResponseEntity.ok(s.checkIn(id));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}} @GetMapping("/members/expiring") public List<Membership> expiring(){return s.expiring();} @GetMapping("/members/{id}/attendance") public Map<String,Object> attendance(@PathVariable Long id){Member m=s.get(id);return Map.of("memberId",id,"memberName",m.getName(),"currentMonthAttendance",s.attendance(id));}}
